#!/usr/bin/env python3
# THE NUMBERS WALK sitting 8 — THE SECOND CENSUS (2026-09-11): THE CLAIMS of Numbers 26:1-65, one manifest for the one draft unit, read
# off this sitting's ledger, every claim LABELED (World/step9/CLAIM_LABELS.md's vocabulary), a machine check where the ink allows — every
# he_contains substring CUT FROM THE SNAPSHOT STORE'S OWN BYTES by the word's CONSONANTS (sitting 6's form). Claim IDs PN26A-01..12
# (Pinchas, chapter 26). Written once (the file must not exist; the ID prefix checked absent from every existing manifest and unit).
# Every source cite is checked against the ledger's CITE INDEX before a byte is written.
import json, os, re, sqlite3, glob
ROOT = _ROOT
DATE = '2026-09-11'
UID, PRE = 'num_26_second_census', 'PN26A'
OUT = f'{ROOT}/logic/oral_audit/manifests/{UID}_claims.json'
assert not os.path.exists(OUT), OUT
for f in glob.glob(f'{ROOT}/logic/oral_audit/manifests/*_claims.json') + glob.glob(f'{ROOT}/logic/units/*.yaml'):
    assert f'{PRE}-' not in open(f, encoding='utf-8').read(), (PRE, f)
led = open(f'{ROOT}/logic/oral_triage/{UID}_{DATE}.md', encoding='utf-8').read().split('## CITE INDEX')[1]
CI = set(re.findall(r'^(Sifrei Bamidbar \d+:\d+|Onkelos Num \d+:\d+)$', led, re.M))
assert len(CI) == 69, len(CI)
db = sqlite3.connect(f'file:{ROOT}/torah_grok.SNAPSHOT-main-51801ca.sqlite?mode=ro', uri=True)
def cut(book, ch, v, word, n, nth=0):
    rows = db.execute("SELECT w.idx, w.he FROM words w JOIN verses v ON w.verse_id=v.id WHERE v.book=? AND v.chapter=? AND v.verse=? ORDER BY w.idx", (book, ch, v)).fetchall()
    plain = lambda h: ''.join(c for c in h if c != '/' and not (0x0591 <= ord(c) <= 0x05C7))
    hit = [(i, h) for i, h in rows if plain(h) == word]
    assert len(hit) > nth and (len(hit) == 1 or nth is not None), (book, ch, v, word, hit)
    idx, he = hit[nth]
    piece = max(he.split('/'), key=len)
    n = min(len(piece), max(n, 6))
    assert n >= 6, (book, ch, v, word, piece)
    return idx, piece[:n]
def hc(ref, word, n, note, nth=0):
    b, cv = ref.split(' '); c, v = map(int, cv.split(':'))
    idx, sub = cut(b, c, v, word, n, nth)
    return {"type": "he_contains", "ref": ref, "idx": idx, "contains": sub, "note": note}
def onk(lo, hi): return '; '.join(f'Onkelos Num 26:{v}' for v in range(lo, hi + 1))
def sif(*rows): return '; '.join(f'Sifrei Bamidbar {r}' for r in rows)

